
#include "main.h"
#include <stdint.h>

// I2C handle generated by STM32CubeMX
extern I2C_HandleTypeDef hi2c1;

// System configuration
#define NUM_BOARDS         4
#define MAGNETS_PER_BOARD  4
#define SENSORS_PER_BOARD  4

// I2C commands
// commands are set in memory and used with HAL to execute the command
#define MAGNET_CONTROL     0x01
#define SENSOR_REQUEST     0x02

// I2C board addresses
const uint8_t BOARD_ADDRESSES[NUM_BOARDS] = {
    0x20, 0x21, 0x22, 0x23
};

// Magnet command variables
// ? target board and target magnet are used with sensor value array to select magnets
// magnet state is either on or off
volatile uint8_t target_board = 0;
volatile uint8_t target_magnet = 0;
volatile uint8_t magnet_state = 0;

// Interrupt flag
// ? signals when any magnet needs to change states
volatile uint8_t magnet_command_pending = 0;

// Sensor data storage
// creates a 2 dimentional array for every configured board and its magnets
uint16_t sensor_values[NUM_BOARDS][SENSORS_PER_BOARD];

// Function prototypes
HAL_StatusTypeDef Set_Magnet(uint8_t board,
                             uint8_t magnet,
                             uint8_t state);

HAL_StatusTypeDef Read_Sensors(uint8_t board);

void Poll_All_Sensors(void);
void Process_Magnet_Command(void);


// =====================================
// MAIN PROGRAM
// =====================================

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_I2C1_Init();

    // main loop
    // majority of time consitst of checking for interrupts and reading sensors
    while (1)
    {
        // ---------------------------------
        // LOOP 1: INTERRUPT-TRIGGERED MAGNET
        // ---------------------------------

        // if the interupt handler detected an interupt from slave board
        if (magnet_command_pending)
        {
            Process_Magnet_Command();
        }

        // ---------------------------------
        // LOOP 2: CONTINUOUS SENSOR POLLING
        // ---------------------------------

        Poll_All_Sensors();
    }
}


// =====================================
// MAGNET CONTROL FUNCTION
// =====================================

HAL_StatusTypeDef Set_Magnet(uint8_t board,
                             uint8_t magnet,
                             uint8_t state)
{
    // Validate inputs
    // if the queried magnet falls outside of existing magnets
    if (board >= NUM_BOARDS ||
        magnet >= MAGNETS_PER_BOARD ||
        state > 1)
    {
        return HAL_ERROR;
    }

    // Prepare command packet
    uint8_t command[3] = {
        MAGNET_CONTROL,
        magnet,
        state
    };

    // Select board address
    // ? shifts 7 bit address to make it 8 bits
    uint16_t address = BOARD_ADDRESSES[board] << 1;

    // Transmit command
    // parameters: 
    //              pointer to a hal_i2c_handle_t
    //              targeted board
    //              transmited message
    //              size of transmited messge
    //              wait 20 milliseconds
    // returns:
    //              status of process
    return HAL_I2C_Master_Transmit(
        &hi2c1,
        address,
        command,
        sizeof(command),
        20
    );
}


// =====================================
// PROCESS PENDING MAGNET COMMAND
// =====================================

void Process_Magnet_Command(void)
{
    uint8_t board;
    uint8_t magnet;
    uint8_t state;

    // Copy command atomically
    // ? primask is supposedly one bit, don't know why its 32 bits here
    uint32_t primask = __get_PRIMASK();
    // dissable interupts
    __disable_irq();

    board = target_board;
    magnet = target_magnet;
    state = magnet_state;

    magnet_command_pending = 0;

    // resumes interupt handling
    __set_PRIMASK(primask);

    // Send magnet command
    HAL_StatusTypeDef status =
        Set_Magnet(board, magnet, state);

    if (status != HAL_OK)
    {
        // Handle I2C transmission error
    }
}


// =====================================
// SENSOR READING FUNCTION
// =====================================

HAL_StatusTypeDef Read_Sensors(uint8_t board)
{
    if (board >= NUM_BOARDS)
    {
        return HAL_ERROR;
    }

    // ? turn 7 bit adress into 8 bit address
    uint16_t address = BOARD_ADDRESSES[board] << 1;

    uint8_t request = SENSOR_REQUEST;

    // Four sensors, two bytes each
    uint8_t rx_buffer[SENSORS_PER_BOARD * 2];
    
    // Request sensor readings
    // Transmit command
    // parameters: 
    //              pointer to a hal_i2c_handle_t
    //              targeted board
    //              transmited message
    //              size of transmited messge
    //              wait 20 milliseconds
    // returns:
    //              status of process
    HAL_StatusTypeDef status =
        HAL_I2C_Master_Transmit(
            &hi2c1,
            address,
            &request,
            1,
            20
        );

    if (status != HAL_OK)
    {
        return status;
    }

    // Receive sensor readings
    // parameters: 
    //              pointer to a hal_i2c_handle_t
    //              targeted board
    //              transmited message
    //              size of transmited messge
    //              wait 20 milliseconds
    // returns:
    //              status of process
    status = HAL_I2C_Master_Receive(
        &hi2c1,
        address,
        rx_buffer,
        sizeof(rx_buffer),
        20
    );

    if (status != HAL_OK)
    {
        return status;
    }

    // Convert bytes into 16-bit values
    for (uint8_t sensor = 0;
         sensor < SENSORS_PER_BOARD;
         sensor++)
    {
        sensor_values[board][sensor] =
            ((uint16_t)rx_buffer[sensor * 2] << 8) |
            rx_buffer[sensor * 2 + 1];
    }

    return HAL_OK;
}


// =====================================
// CONTINUOUS SENSOR POLLING LOOP
// =====================================

// continuously checks sensor inputs
void Poll_All_Sensors(void)
{
    for (uint8_t board = 0;
         board < NUM_BOARDS;
         board++)
    {
        // Service magnet commands between boards
        // same if statement is in main loop for redundancy
        if (magnet_command_pending)
        {
            Process_Magnet_Command();
        }

        // Poll current board
        HAL_StatusTypeDef status = Read_Sensors(board);

        if (status != HAL_OK)
        {
            // Handle sensor communication error
        }
    }
}


// =====================================
// EXTERNAL INTERRUPT CALLBACK
// =====================================

// this function is called whenever a GPIO EXTI interrupt reaches the HAL handler
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if (GPIO_Pin == COMMAND_Pin)
    {
        // Example magnet command
        target_board = 0;
        target_magnet = 2;
        magnet_state = 1;

        // Signal main loop to transmit
        magnet_command_pending = 1;
    }
}
